\begin{align*}
 P:\quad &(180,0)\to(172,1)\to(112,0)\to(209,1)\\
         &\to(157,2)\to(148,1)\to(186,2)\to(86,3),\\
 J:\quad &(180,0)\to(211,1)\to(218,2)\to(86,3).
\end{align*}
Again the lengths are seven and three.

\begin{lemma}\label{lem:bypass}
$P$ and $J$ are halting-equivalent from every common configuration.
Every exceptional matching block is weakly time-improving.
\end{lemma}
\begin{proof}
Use the displayed blocks at $180/1$ and identical one-step blocks
elsewhere. Each block has positive finite length, has no interior halt,
and ends in an identical complete configuration. Induction on any finite
halting trace translates it in either direction.
\end{proof}

\begin{lemma}[Two-zero entry invariant]\label{lem:zeros}
In a $J$ computation starting in state 0, every visit to 112 scans a zero
and has a zero immediately to its right.
\end{lemma}
\begin{proof}
Every visit to 172 was entered by $116/0$, which writes zero and moves
right. If its scanned bit is zero, its zero branch writes that zero and
moves left into 112. The new scanned cell is the zero written by 116;
the immediate right cell is the zero just scanned by 172. Neither 172
nor 112 is the initial state. The complete incoming lists establish the
invariant at every finite time, with no restriction on the initial tape.
\end{proof}

